export const ICON_NAMES = Object.freeze(Object.keys(ICONS));

function lookup(concept) {
  if (!Object.hasOwn(ICONS, concept)) throw new Error(`fabric-icons: unknown icon concept "${concept}"`);
  return ICONS[concept];
}

// Markup for inside <defs>: one <symbol id="fi-<concept>"> (plus its hoisted definitions) per requested concept.
export function iconDefs(names = ICON_NAMES) {
  const list = typeof names === 'string' ? [names] : [...names];
  return [...new Set(list)]
    .map((name) => {
      const { viewBox, defs, body } = lookup(name);
      return `${defs}<symbol id="fi-${name}" viewBox="${viewBox}">${body}</symbol>`;
    })
    .join('\n');
}

const num = (v) => String(Math.round(v * 100) / 100);

// A size x size <use> of the concept's symbol, centered on (cx, cy).
export function icon(concept, cx, cy, size) {
  lookup(concept);
  if (![cx, cy, size].every(Number.isFinite) || size <= 0) {
    throw new Error(`fabric-icons: bad position/size for "${concept}"`);
  }
  const ref = `#fi-${concept}`;
  return `<use href="${ref}" xlink:href="${ref}" x="${num(cx - size / 2)}" y="${num(cy - size / 2)}" width="${num(size)}" height="${num(size)}"/>`;
}

